<template><section class="handoff-panel"><h2>{{ __('Create delivery work') }}</h2><p class="text-muted">{{ __('Link a sales or CRM record to one delivery project. Repeating the handoff opens the existing project.') }}</p><p v-if="error" role="alert">{{ error }}</p><form @submit.prevent="create"><label>{{ __('Source type') }}<select v-model="sourceType" class="field"><option value="Sales Order">{{ __('Sales Order') }}</option><option value="CRM Deal">{{ __('CRM Deal') }}</option><option value="Opportunity">{{ __('Opportunity') }}</option></select></label><label>{{ __('Source record ID') }}<input v-model="sourceName" class="field" required /></label><label>{{ __('Project name') }}<input v-model="title" class="field" required /></label><label>{{ __('Project template (optional)') }}<input v-model="template" class="field" :placeholder="__('Existing template project ID')" /></label><button class="btn-primary" :disabled="busy">{{ busy ? __('Creating…') : __('Create delivery project') }}</button></form><p v-if="result" role="status">{{ result.created ? __('Delivery project created.') : __('This source already has a delivery project.') }} <RouterLink :to="{path:'/board',query:{project:result.project}}">{{ __('Open project') }}</RouterLink></p></section></template>
<script setup>
import {ref} from 'vue'
import {call} from 'frappe-ui'
import { __ } from '@/translation'
const emit=defineEmits(['created'])
const sourceType=ref('Sales Order'),sourceName=ref(''),title=ref(''),template=ref(''),busy=ref(false),error=ref(''),result=ref(null)
async function create(){busy.value=true;error.value='';result.value=null;try{result.value=await call('pulse.api.handoffs.create',{source_doctype:sourceType.value,source_name:sourceName.value,project_name:title.value,template:template.value||null});emit('created',result.value)}catch(e){error.value=e.messages?.join(' ')||__('Unable to create delivery work. Check the source and your permissions.')}finally{busy.value=false}}
</script>
<style scoped>.handoff-panel{padding:20px;border:1px solid var(--border-color,#e6e8ec);border-radius:8px;margin:16px 0}.handoff-panel h2{font-weight:600;font-size:16px}.handoff-panel p{font-size:13px;margin:8px 0}.handoff-panel form{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:16px}.handoff-panel label{display:grid;gap:6px;font-size:13px}.handoff-panel button{justify-self:start}@media(max-width:700px){.handoff-panel form{grid-template-columns:1fr}}</style>
